import{z as B,x as i,o as t,c as d,q as s,j as l,D as E,d as r,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"线程与共享地址空间","description":"","frontmatter":{"title":"线程与共享地址空间","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/thread-shared-addr.md","filePath":"cs/thread-shared-addr.md","lastUpdated":1791413859000}'),p={name:"cs/thread-shared-addr.md"};function m(h,a,D,u,P,f){const A=i("Mermaid");return t(),d("div",null,[a[2]||(a[2]=s('<h1 id="线程与共享地址空间" tabindex="-1">线程与共享地址空间 <a class="header-anchor" href="#线程与共享地址空间" aria-label="Permalink to &quot;线程与共享地址空间&quot;">​</a></h1><div class="epigraph"><p>线程是进程内部的一条控制流；同一进程的线程共享地址空间，各有各的栈与寄存器。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Birrell, An Introduction to Programming with Threads 整理</footer></div><p><a href="/cs/process-groups">上一课</a>让一份映像对应一份地址空间、一条执行流。缺口是：服务器与运行时往往要在<strong>同一份用户页</strong>里同时算多件事——若每件事都 fork 一份进程，页表、文件表都复制，太重。本课只把线程定义为共享地址空间的执行流。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进程切换要换页表根，<a href="/cs/tlb-translate">TLB</a> 开销大；进程间通信还要走后课的管道。同一程序里的请求处理、GC 与计算，本来就该看见同一堆。缺口不是新的虚存硬件，而是在一个 PCB 下挂多套寄存器与栈，代码段、数据段、打开文件默认共享。</p><p>本课不讲如何互斥地改这份共享堆，那是竞争与锁的课。这里只钉共享与私有各是什么。</p><p><span class="marginnote">POSIX 线程是用户可见的接口。内核线程与用户级线程的映射（1:1、N:1）是实现，主干先按「内核可调度的一条控制流」理解。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个线程：私有寄存器、私有用户栈、私有线程局部存储；共享：页表、堆、全局数据、文件描述符表。创建线程不复制地址空间，只分配栈与线程控制块。进程退出则其中所有线程一起结束。</p>',9)),(t(),l(o,null,{default:E(()=>[n(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROC%5B%22%E8%BF%9B%E7%A8%8B%3A%20%E9%A1%B5%E8%A1%A8%E4%B8%8E%E6%96%87%E4%BB%B6%22%5D%20--%3E%20T1%5B%22%E7%BA%BF%E7%A8%8B%3A%20%E6%A0%88%E4%B8%8E%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20PROC%20--%3E%20T2%5B%22%E7%BA%BF%E7%A8%8B%3A%20%E6%A0%88%E4%B8%8E%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20PROC%20--%3E%20HEAP%5B%22%E5%85%B1%E4%BA%AB%E5%A0%86%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"用户级线程库可以在一个内核线程上自己切换栈，内核看不见；本课后头的调度默认调度内核线程。两种实现的细节不展开。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：「上下文切换」就是把 CPU 上正在跑的那组寄存器存进内存、再换上另一组。线程切换只换寄存器和栈指针；进程切换还要换页表根——多换的这一步才是贵的那部分。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"共享地址空间让指针可以直接递给「另一个执行流」，无需序列化。代价是：栈溢出、野指针会破坏所有线程的堆。内核仍然按线程选谁上 CPU；页表根在同进程线程之间通常不变，切换比跨进程便宜。",-1)),a[7]||(a[7]=e("p",null,[r("运行时 GC 扫描的是进程堆，必须看见所有线程的根（寄存器与栈）。"),e("a",{href:"/cs/kernel-user"},"内核与用户态"),r("课的 GC 直觉在这里变成：根是每条线程一份，堆是一份。本课不写扫描算法。")],-1)),a[8]||(a[8]=e("p",null,"同进程切换与跨进程切换的账单差在哪：",-1)),(t(),l(o,null,{default:E(()=>[n(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SW%5B%22%E8%B0%83%E5%BA%A6%E5%86%B3%E5%AE%9A%E6%8D%A2%E4%BA%BA%22%5D%20--%3E%20SAME%7B%22%E5%90%8C%E8%BF%9B%E7%A8%8B%E5%86%85%E5%88%87%E6%8D%A2%3F%22%7D%0A%20%20SAME%20--%3E%7C%22%E6%98%AF%22%7C%20T%5B%22%E6%8D%A2%E5%AF%84%E5%AD%98%E5%99%A8%E4%B8%8E%E6%A0%88%E6%8C%87%E9%92%88%22%5D%0A%20%20T%20--%3E%20KEEP%5B%22%E9%A1%B5%E8%A1%A8%E6%A0%B9%E4%B8%8D%E5%8F%98%2C%20TLB%20%E4%BF%9D%E7%95%99%22%5D%0A%20%20SAME%20--%3E%7C%22%E5%90%A6%22%7C%20P%5B%22%E8%BF%9E%E9%A1%B5%E8%A1%A8%E6%A0%B9%E4%B8%80%E8%B5%B7%E6%8D%A2%22%5D%0A%20%20P%20--%3E%20FLUSH%5B%22TLB%20%E5%A4%A7%E9%9D%A2%E7%A7%AF%E5%A4%B1%E6%95%88%22%5D%0A%20%20KEEP%20--%3E%20GO%5B%22%E7%AB%8B%E5%88%BB%E7%83%AD%E7%9D%80%E7%BB%A7%E7%BB%AD%E8%B7%91%22%5D%0A%20%20FLUSH%20--%3E%20COLD%5B%22%E5%A4%B4%E5%87%A0%E6%AC%A1%E8%AE%BF%E5%AD%98%E5%85%A8%E8%A6%81%E6%9F%A5%E9%A1%B5%E8%A1%A8%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=s('<p><span class="marginnote">数字实例：TLB 通常只有几十到上千个条目。换进程后 TLB 大量作废，随后的访存要重新走多级页表（四级页表最坏多访存 4 次），这就是跨进程切换比同进程线程切换贵的量化来源。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入协程与绿色线程的全部语义，不把 GPU 线程束请进来，也不讲数据竞争的形式定义——后面的课才把「同时写同一地址」收成临界区。fork 之后线程数如何收口，Unix 有明确规定，主干不背手册。</p><p>errno 与浮点环境是否线程局部，属于 ABI；主干只要求寄存器与栈私有。</p><p><span class="marginnote">常见误区：初学者容易以为线程间传数据要「拷贝一份」——同进程内传指针就是传一个地址值，零拷贝。代价是同样没有任何隔离：一个线程的野指针能砸坏所有线程共用的堆。</span></p><p>后课默认：同进程线程共享用户地址空间，各有栈与寄存器。内核如何把 CPU 从一条线程挪到另一条，后课讲上下文切换。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>线程是共享地址空间的控制流；私有的是栈与寄存器。</li><li>同进程切换通常不换页表根，比换进程轻。</li><li>共享堆上的互斥仍未给出。</li><li>出处：Silberschatz et al., <em>OSC</em>；Birrell, <em>An Introduction to Programming with Threads</em>, 1989。</li></ul>',8))])}const S=B(p,[["render",m]]);export{T as __pageData,S as default};
